-- 0130: the verb tables (الصرف الصغير) of the Ghāfir 40:2–3 roots move into AL (22-BAB carrier
-- ar_ling_root_form_paradigm), from QR's checked tables (qr_sarf_verb). One row per root × form, and
-- per bāb where one set of letters has two abwāb with two meanings (شدد, عزز). paradigm_json keeps
-- AL's keys (past, present, masadir, active_participle, passive_participle, meaning) and adds what
-- the sheet needs: passive_past, passive_present, imperative, prohibition, noun_of_place_time,
-- noun_of_instrument, derived (فعيل/فعّال/أفعل…), the GT ids, Qurʾān count and citation.
INSERT OR REPLACE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:اله:I', 'أَلَهَ يَأْلَهُ', 'verb_form', 'I', 'mahmuz_fa', '{"past": "أَلَهَ", "present": "يَأْلَهُ", "masadir": ["إِلَاهَةً", "أُلُوهَةً", "أُلُوهِيَّةً"], "active_participle": "آلِهٌ", "active_participle_gt": "GT:derivation_type:active_participle", "passive_past": "أُلِهَ", "passive_present": "يُؤْلَهُ", "passive_participle": "مَأْلُوهٌ", "imperative": "اِيلَهْ", "prohibition": "لَا تَأْلَهْ", "noun_of_place_time": ["مَأْلَهٌ"], "meaning": "to worship", "note": "The Qurʾān does not use the verb. إِلَٰه is on فِعَال in the sense of مَفْعُول: the one worshipped (مَأْلُوه).", "bab_gt": "GT:form_family:bab_fataha", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:mahmuz_fa", "route_gt": "GT:taddiya_route:binafsihi", "quran_n": 0, "full_table": true, "source_ref": "qr_sarf_verb SV:اله:I (checked against the muṣḥaf and the lexicons)"}', 'kmaps_synth', 'qr_sarf_verb SV:اله:I', 'bab_fataha', 'live', 'AL:150-FORM:SF:22-BAB:P', 'to worship');
INSERT OR REPLACE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:توب:I', 'تَابَ يَتُوبُ', 'verb_form', 'I', 'hollow_w', '{"past": "تَابَ", "present": "يَتُوبُ", "masadir": ["تَوْبًا", "تَوْبَةً", "مَتَابًا"], "active_participle": "تَائِبٌ", "active_participle_gt": "GT:derivation_type:active_participle", "passive_past": "تِيبَ عَلَيْهِ", "passive_present": "يُتَابُ عَلَيْهِ", "passive_participle": "مَتُوبٌ عَلَيْهِ", "imperative": "تُبْ", "prohibition": "لَا تَتُبْ", "noun_of_place_time": ["مَتَابٌ"], "derived": [{"word": "تَوَّابٌ", "gt": "GT:derivation_type:mubalagha", "pattern": "فَعَّال", "meaning": "turning again and again"}], "meaning": "to turn back (in repentance); of God: to turn to someone in mercy", "note": "Intransitive: its مجهول is made with its preposition — تِيبَ عَلَيْهِ.", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:hollow_w", "route_gt": "GT:taddiya_route:biharf", "quran_n": 63, "cite": {"surah": 66, "ayah": 8, "needle": "توبوا الي الله"}, "full_table": true, "source_ref": "qr_sarf_verb SV:توب:I (checked against the muṣḥaf and the lexicons)"}', 'kmaps_synth', 'qr_sarf_verb SV:توب:I', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P', 'to turn back (in repentance); of God: to turn to someone in mercy');
INSERT OR REPLACE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:شدد:I:daraba', 'شَدَّ يَشِدُّ', 'verb_form', 'I', 'doubled', '{"past": "شَدَّ", "present": "يَشِدُّ", "masadir": ["شِدَّةً"], "active_participle": "شَدِيدٌ", "active_participle_gt": "GT:derivation_type:sifa_mushabbaha", "derived": [{"word": "أَشَدُّ", "gt": "GT:derivation_type:tafdil", "pattern": "أَفْعَل", "meaning": "stronger, more severe"}], "meaning": "to be strong, hard, severe", "note": "A verb of state: no مجهول; its describing word is the صفة مشبهة شَدِيد.", "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:doubled", "route_gt": "GT:taddiya_route:lazim", "quran_n": 0, "full_table": true, "source_ref": "qr_sarf_verb SV:شدد:I:daraba (checked against the muṣḥaf and the lexicons)"}', 'kmaps_synth', 'qr_sarf_verb SV:شدد:I:daraba', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P', 'to be strong, hard, severe');
INSERT OR REPLACE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code, name_en) VALUES ('PAR:شدد:I:nasara', 'شَدَّ يَشُدُّ', 'verb_form', 'I', 'doubled', '{"past": "شَدَّ", "present": "يَشُدُّ", "masadir": ["شَدًّا"], "active_participle": "شَادٌّ", "active_participle_gt": "GT:derivation_type:active_participle", "passive_past": "شُدَّ", "passive_present": "يُشَدُّ", "passive_participle": "مَشْدُودٌ", "imperative": "اُشْدُدْ", "prohibition": "لَا تَشُدَّ", "noun_of_place_time": ["مَشَدٌّ"], "meaning": "to bind fast; to strengthen", "note": "Same letters, another باب: شَدَّ يَشِدُّ (be strong) and شَدَّهُ يَشُدُّهُ (bind it fast).", "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:doubled", "route_gt": "GT:taddiya_route:binafsihi", "quran_n": 6, "cite": {"surah": 47, "ayah": 4, "needle": "فشدوا الوثاق"}, "full_table": true, "source_ref": "qr_sarf_verb SV:شدد:I:nasara (checked against the muṣḥaf and the lexicons)"}', 'kmaps_synth', 'qr_sarf_verb SV:شدد:I:nasara', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P', 'to bind fast; to strengthen');
